    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.getLeft();
    if (left == null) {
        return node;
    }
    TreeNode<T> leftRight = left.getRight();

    // Rotate
    left.setRight(node);
    node.setLeft(leftRight);

    // Update parent references
    TreeNode<T> parent = node.getParent();
    left.setParent(parent);
    if (leftRight != null) {
        leftRight.setParent(node);
    }
    if (parent != null) {
        if (node == parent.getRight()) {
            parent.setRight(left);
        } else {
            parent.setLeft(left);
        }
    }
    node.setParent(left);

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> leftChild = node.left;
    // Move left child's right subtree to node's left
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }
    // Link node as right child of left child
    leftChild.right = node;
    leftChild.parent = node.parent;
    node.parent = leftChild;
    // Update parent reference to point to new root
    if (leftChild.parent != null) {
        if (leftChild.parent.left == node) {
            leftChild.parent.left = leftChild;
        } else if (leftChild.parent.right == node) {
            leftChild.parent.right = leftChild;
        }
    }
    return leftChild;
}

public static void addToClassPath(Vector<URL> cpV,String dir){
    if (cpV == null) throw new IllegalArgumentException("Classpath vector cannot be null");
    if (dir == null) throw new IllegalArgumentException("Directory path cannot be null");
    java.io.File dirFile = new java.io.File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()){
        return;
    }
    java.io.File[] jarFiles = dirFile.listFiles(new java.io.FilenameFilter(){
        public boolean accept(java.io.File d, String name){
            return name.toLowerCase().endsWith(".jar");
        }
    });
    if (jarFiles == null){
        return;
    }
    for (java.io.File jar : jarFiles){
        try{
            java.net.URL url = jar.toURI().toURL();
            cpV.add(url);
        } catch (java.net.MalformedURLException e){
            // ignore malformed URLs
        }
    }
}

