public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null || dir == null) {
        return;
    }
    File dirFile = new File(dir);
    if (!dirFile.isDirectory()) {
        return;
    }
    File[] jarFiles = dirFile.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File d, String name) {
            return name != null && name.toLowerCase().endsWith(".jar");
        }
    });
    if (jarFiles == null) {
        return;
    }
    for (File jar : jarFiles) {
        try {
            cpV.add(jar.toURI().toURL());
        } catch (Exception e) {
            // Ignore malformed URLs or security exceptions; continue with next file
        }
    }
}

public static void addToClassPath(Vector<URL> cpV,String dir) {
    try {
        File folder = new File(dir);
        if (!folder.isDirectory()) {
            return;
        }
        File[] files = folder.listFiles();
        if (files != null) {
            for (File f : files) {
                if (f.isFile() && f.getName().toLowerCase().endsWith(".jar")) {
                    cpV.add(f.toURI().toURL());
                }
            }
        }
    } catch (MalformedURLException e) {
        // ignore malformed URLs
