public long contentLength(){
    try{
        // Attempt to retrieve the content length from the underlying request object
        Object req = this.request; // assumes a field named 'request' exists
        if (req == null) {
            return -1L;
        }
        // Try the modern getContentLengthLong() first
        try {
            java.lang.reflect.Method m = req.getClass().getMethod("getContentLengthLong");
            Object result = m.invoke(req);
            if (result instanceof Long) {
                return (Long) result;
            }
        } catch (Exception ignored) { }
        // Fallback to legacy getContentLength()
        try {
            java.lang.reflect.Method m = req.getClass().getMethod("getContentLength");
            Object result = m.invoke(req);
            if (result instanceof Integer) {
                return ((Integer) result).longValue();
            }
        } catch (Exception ignored) { }
        // If all else fails, return -1 indicating unknown length
        return -1L;
    } catch (Exception e){
        return -1L;
    }
}

public long contentLength(){
    // Attempt to retrieve content length from HttpServletRequest if available
    try {
        if (request != null) {
            long len = request.getContentLengthLong();
            if (len >= 0) {
                return len;
            }
            // Fallback: parse the Content-Length header if length was not set
            String header = request.getHeader("Content-Length");
            if (header != null) {
                try {
                    return Long.parseLong(header);
                } catch (NumberFormatException ignore) {
                    // ignore and fall through
                }
            }
        }
    } catch (Exception e) {
        // Log or handle unexpected exceptions if necessary
    }
    // If request is null or no valid length is found, return 0
    return 0L;
}

