public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    // If directory, first schedule deletion for all children
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    try {
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Unable to register delete on exit for " + file, e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    // Use a stack to perform a depth‑first traversal so that files are scheduled for deletion
    // after their contents have been queued, which is required for directories.
    java.util.ArrayDeque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children == null) {
                throw new IOException("Unable to list directory contents: " + current);
            }
            for (File child : children) {
                stack.push(child);
            }
        }
        if (!current.deleteOnExit()) {
            throw new IOException("Failed to schedule deletion of: " + current);
        }
    }
}

