    if (target == null || resultMap == null || resultMap.isEmpty()){
        return;
    }
    // Separate vertices into two partitions: first half left, second half right
    java.util.List<V> left = new java.util.ArrayList<>();
    java.util.List<V> right = new java.util.ArrayList<>();
    int idx = 0;
    int half = resultMap.size() / 2;
    for (V v : resultMap.values()){
        if (idx < half){
            left.add(v);
        } else{
            right.add(v);
        }
        idx++;
    }
    // Add vertices to the graph
    for (V v : left){
        target.addVertex(v);
    }
    for (V v : right){
        target.addVertex(v);
    }
    // Create a complete bipartite graph: edges between every left and right vertex
    for (V lv : left){
        for (V rv : right){
            target.addEdge(lv, rv);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null || resultMap == null) return;
    // Add all vertices to the target graph
    for (V vertex : resultMap.values()){
        if (!target.containsVertex(vertex)){
            target.addVertex(vertex);
        }
    }
    int totalVertices = resultMap.size();
    if (totalVertices < 2) return; // not enough vertices for a bipartite graph
    int half = totalVertices / 2;
    List<V> left = new ArrayList<>(half);
    List<V> right = new ArrayList<>(totalVertices - half);
    int idx = 0;
    for (V vertex : resultMap.values()){
        if (idx < half){
            left.add(vertex);
        } else {
            right.add(vertex);
        }
        idx++;
    }
    // Create all edges between vertices in left and right partitions
    for (V u : left){
        for (V v : right){
            if (!u.equals(v)){
                target.addEdge(u, v);
            }
        }
    }
}

