        throw new IllegalArgumentException("target and resultMap must not be null");
    }
    try {
        // Add all vertices from the map
        for (V vertex : resultMap.values()) {
            target.addVertex(vertex);
        }
        // Create a complete graph (edges between all distinct pairs)
        List<V> vertices = new ArrayList<>(resultMap.values());
        int size = vertices.size();
        for (int i = 0; i < size; i++) {
            V v1 = vertices.get(i);
            for (int j = i + 1; j < size; j++) {
                V v2 = vertices.get(j);
                // addEdge may return an edge instance; ignore it
                target.addEdge(v1, v2);
            }
        }
    } catch (Exception ex) {
        // Log or rethrow as unchecked to indicate failure in graph construction
        throw new RuntimeException("Failed to generate graph", ex);
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        return;
    }
    // Ensure all vertices from the map are present in the graph
    for (V vertex : resultMap.values()) {
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
    }
    // Create two partitions deterministically: split vertices by sorted key order
    List<String> sortedKeys = new ArrayList<>(resultMap.keySet());
    Collections.sort(sortedKeys);
    int mid = sortedKeys.size() / 2;
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (int i = 0; i < sortedKeys.size(); i++) {
        V v = resultMap.get(sortedKeys.get(i));
        if (i < mid) {
            left.add(v);
        } else {
            right.add(v);
        }
    }
    // Add edges only between vertices in different partitions
    for (V u : left) {
        for (V w : right) {
            // Avoid duplicate edges if the graph is undirected
            if (!target.containsEdge(u, w) && !target.containsEdge(w, u)) {
                target.addEdge(u, w);
            }
        }
    }
}

