public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    try {
        CodedOutputStream cos = CodedOutputStream.newInstance(out);
        cos.writeRawVarint32(size);
        schema.writeTo(message, buffer);
        buffer.flushTo(out);
        return size;
    } finally {
        buffer.release();
    }
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    buffer.clear();
    schema.writeTo(buffer, message);
    int size = buffer.getReadPosition();
    if (size < 0) {
        throw new IOException("Failed to determine size of serialized message");
    }
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    cos.writeRawBytes(buffer.getBuffer(), 0, size);
    cos.flush();
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Compute the size of the serialized message
    int size = schema.getSerializedSize(message);
    // Prefix the output with the size (big-endian 4‑byte length)
    out.write(new byte[]{(byte)(size >> 24), (byte)(size >> 16), (byte)(size >> 8), (byte)size});
    // Serialize the message itself into the output stream
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    schema.writeTo(message, cos);
    cos.flush();
    return size;
}

