public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        return new Mappings();
    }
    // Retrieve the current mapping for the specified index (implementation provided elsewhere)
    Mappings current = getCurrentMapping(tableName);
    if (current == null) {
        return new Mappings();
    }
    Mappings diff = new Mappings();
    // Iterate over each type defined in the current mapping
    for (String type : current.getTypes()) {
        // Skip the internal _source config to avoid conflicts with the current index
        if ("_source".equals(type)) {
            continue;
        }
        Map<String, Object> currentProps = current.getProperties(type);
        Map<String, Object> historyProps = (mappings != null) ? mappings.getProperties(type) : Collections.emptyMap();
        Map<String, Object> missingProps = new LinkedHashMap<>();
        // Identify properties that exist in the current mapping but absent in the input (history) mapping
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            if (!historyProps.containsKey(entry.getKey())) {
                missingProps.put(entry.getKey(), entry.getValue());
            }
        }
        // If there are missing properties, add them to the diff result
        if (!missingProps.isEmpty()) {
            diff.putType(type, missingProps);
        }
    }
    return diff;
}

