protected List<TimeRange> buildTimeRanges(long start,long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start > end) {
        return ranges; // return empty list if invalid range
    }
    final long MAX_DURATION = FETCH_DATA_DURATION;
    long current = start;
    while (current < end) {
        long next = Math.min(current + MAX_DURATION, end);
        // Ensure we do not create zero-length ranges
        if (next <= current) {
            break;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

