public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (lb == null) {
        return null;
    }
    if (str == null) {
        // nothing to write, just return the buffer as-is
        return lb;
    }
    // Encode the string into UTF‑8
    byte[] utf8Bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
    // Write the bytes into the LinkedBuffer
    // Assumes LinkedBuffer has a write(byte[], int, int) method
    lb.write(utf8Bytes, 0, utf8Bytes.length);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    if(str == null || lb == null){
        return lb;
    }
    try{
        byte[] utf8Bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
        try{
            java.lang.reflect.Method m = lb.getClass().getMethod("writeBytes", byte[].class);
            m.invoke(lb, utf8Bytes);
        }catch(NoSuchMethodException nsme){
            try{
                java.lang.reflect.Method m2 = lb.getClass().getMethod("write", byte[].class, int.class, int.class);
                m2.invoke(lb, utf8Bytes, 0, utf8Bytes.length);
            }catch(Exception ex){
                throw new RuntimeException("No suitable write method on LinkedBuffer", ex);
            }
        }
    }catch(Exception e){
        throw new RuntimeException("Failed to write UTF-8 string", e);
    }
    return lb;
}

