public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int start = 0;
    // If the path is absolute, ignore the leading '/'
    if (path.startsWith("/") && path.length() > 1) {
        start = 1;
    }
    String relevant = path.substring(start);
    // split on '/', ignoring empty segments that may arise from consecutive slashes
    String[] parts = relevant.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String segmentValue = part;
        if (decode) {
            try {
