public InputStream next() throws IOException {
    try {
        if (filesIterator == null) {
            return null; // no iterator available
        }
        if (!filesIterator.hasNext()) {
            return null; // no more files
        }
        File f = filesIterator.next();
        if (f == null) {
            return null; // defensive check
        }
        return new FileInputStream(f);
    } catch (IOException e) {
        throw e; // propagate IO exceptions
    } catch (Exception e) {
        throw new IOException("Unexpected error while retrieving next file", e);
    }
}

public InputStream next() throws IOException {
    if (fileIterator == null || !fileIterator.hasNext()) {
        return null;
    }
    java.io.File nextFile = fileIterator.next();
    if (nextFile == null) {
        return null;
    }
