                "String length must be 1 to convert to Character: " + str);
        }
        return str.charAt(0);
    }

    // If a Number, use its integer value as the Unicode code point
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }

    // If a Boolean, map true/false to '1'/'0'
    if (value instanceof Boolean) {
        return (char) (((Boolean) value) ? '1' : '0');
    }

    // Unsupported type
    throw new Exception("Cannot convert value of type " + value.getClass().getName()
            + " to Character");
