public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd to skip even numbers
    }
    while (true) {
        boolean isPrime = true;
        if (candidate <= 1) {
            isPrime = false;
        } else if (candidate == 2) {
            isPrime = true;
        } else if (candidate % 2 == 0) {
            isPrime = false;
        } else {
            int sqrt = (int)Math.sqrt(candidate);
            for (int i = 3; i <= sqrt; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // skip even numbers
        // Safety check to avoid infinite loop on overflow
        if (candidate < 0) {
            throw new OutOfMemoryError("Prime number overflow while searching for next prime");
        }
    }
}

