@Override
public String readString() throws IOException {
    // Read the length of the string
    int len = readInt(); // assumes readInt() is available
    // Return null for a sentinel length (e.g., -1)
    if (len == -1) {
        return null;
    }
    // Guard against negative lengths
    if (len < 0) {
        throw new IOException("String length cannot be negative: " + len);
    }
    // Read bytes into a buffer
    byte[] bytes = new byte[len];
    int offset = 0;
    while (offset < len) {
        int read = read(bytes, offset, len - offset); // assumes read(byte[],int,int) is available
        if (read < 0) {
            throw new EOFException("End of stream reached before reading string");
        }
        offset += read;
    }
    // Convert bytes to a String using UTF‑8 encoding
    return new String(bytes, StandardCharsets.UTF_8);
}

