        Object obj = null;
        switch(val.getValueType()){
            case STRING:
                obj = ((JsonString) val).getString();
                break;
            case NUMBER:
                JsonNumber num = (JsonNumber) val;
                if (num.isIntegral()){
                    obj = num.longValue();
                } else {
                    obj = num.doubleValue();
                }
                break;
            case TRUE:
            case FALSE:
                obj = val == JsonValue.TRUE;
                break;
            case NULL:
                obj = null;
                break;
            case OBJECT:
                obj = jsonObject.getJsonObject(key);
                break;
            case ARRAY:
                obj = jsonObject.getJsonArray(key);
                break;
            default:
                obj = null;
        }
