    Set<V> larger = set1.size() <= set2.size() ? set2 : set1;
    // Create a new set from the smaller collection and retain only elements present in the larger
    Set<V> result = new HashSet<>(smaller);
    result.retainAll(larger);
    return result;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    try {
        if (set1 == null || set2 == null) {
            return new java.util.HashSet<>();
        }
        Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
        Set<V> larger = set1.size() > set2.size() ? set1 : set2;
        Set<V> result = new java.util.HashSet<>(smaller.size());
        for (V element : smaller) {
            if (larger.contains(element)) {
                result.add(element);
            }
        }
        return result;
    } catch (Exception ex) {
        throw new RuntimeException("Intersection calculation failed", ex);
    }
}

