protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assume there is a root node reference named "root" of type Category.
        if (root == null) {
            return 0;
        }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category parent = stack.pop();
            java.util.List<Category> children = parent.getChildren();
            if (children == null) {
                continue;
            }
            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                // If the child node is inactive, remove it from its parent.
                if (!child.isActive()) {
                    it.remove();
                    removedCount++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // Handle unexpected runtime issues gracefully.
        // Logging the exception is beyond this snippet's scope.
    }
    return removedCount;
}

