            } catch (NoSuchMethodError | IllegalAccessError | IllegalArgumentException e) {
                // Node does not expose 'isActive'; skip removal
            }
        }
    } catch (Exception e) {
        // Log or silently ignore to avoid disrupting caller
        // e.g., Logger.getLogger(getClass().getName()).log(Level.WARNING, null, e);
    }
    return removedCount;
}

protected int removeUnusedNodes(){
