    java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category node = stack.pop();
        if (!node.isActive()) {
            if (node.getParent() != null) {
                node.getParent().removeChild(node);
                removed++;
            }
            continue;
        }
        java.util.Iterator<? extends Category> it = node.getChildren().iterator();
        while (it.hasNext()) {
            stack.push(it.next());
        }
    }
    return removed;
}

