final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Find the table offset for the requested UTF‑8 constant pool entry.
    int entryOffset = getConstantPoolOffset(constantPoolEntryIndex);
    // The entry starts with a tag byte (0x01). Skip it first.
    int pos = entryOffset + 1;
    // Read the 16‑bit length that precedes the UTF‑8 bytes.
    int length = ((classFileBuffer[pos] & 0xFF) << 8) | (classFileBuffer[pos + 1] & 0xFF);
    // Advance past the length field.
    pos += 2;
    // Decode the UTF‑8 byte sequence into a Java String.
    return new String(classFileBuffer, pos, length, StandardCharsets.UTF_8);
}

final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    try{
        if (classFileBuffer == null || classFileBuffer.length < 10) {
            throw new IllegalArgumentException("classFileBuffer is invalid");
        }
        // constant_pool_count is stored after the first 8 bytes
        int cpCount = ((classFileBuffer[8] & 0xFF) << 8) | (classFileBuffer[9] & 0xFF);
        if (constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= cpCount) {
            throw new IllegalArgumentException("Invalid constant pool index");
        }
        int offset = 10; // start of the first constant pool entry
        for (int i = 1; i < constantPoolEntryIndex; i++) {
            int tag = classFileBuffer[offset] & 0xFF;
            offset++; // move past tag
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
                    offset += 2 + len;
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                    offset += 4;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    offset += 8;
                    i++; // long and double occupy two entries
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                    offset += 2;
                    break;
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 12: // CONSTANT_NameAndType
                    offset += 4;
                    break;
                case 15: // CONSTANT_MethodHandle
                    offset += 3;
                    break;
                case 16: // CONSTANT_MethodType
                    offset += 2;
                    break;
                case 18: // CONSTANT_InvokeDynamic
                    offset += 4;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
            }
            if (offset > classFileBuffer.length) {
                throw new IllegalArgumentException("Malformed constant pool");
            }
        }
        // Now at the target entry
        int tag = classFileBuffer[offset] & 0xFF;
        if (tag != 1) {
            throw new IllegalArgumentException("Constant pool entry is not a Utf8");
        }
        offset++; // skip tag
        int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
        offset += 2;
        if (length > classFileBuffer.length - offset) {
            throw new IllegalArgumentException("Utf8 length exceeds buffer");
        }
        if (charBuffer.length < length) {
            throw new IllegalArgumentException("Provided charBuffer is too small");
        }
        java.nio.charset.StandardCharsets utf8 = java.nio.charset.StandardCharsets.UTF_8;
        byte[] utfBytes = new byte[length];
        System.arraycopy(classFileBuffer, offset, utfBytes, 0, length);
        String result = new String(utfBytes, utf8);
        result.getChars(0, length, charBuffer, 0);
        return result;
    } catch (Exception e){
        throw new RuntimeException("Failed to read Utf8 constant pool entry", e);
    }
}

