    if (predicate == null || start == null || stop == null){
        throw new IllegalArgumentException("Arguments must not be null");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (true){
        Node current = circ.node();
        if (current.equals(stop)){
            return new OuterFaceCirculator(stop, dir);
        }
        if (predicate.test(current)){
            return circ;
        }
        circ = circ.next();
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Traverse outward along the face until we either find a node that satisfies the predicate
    // or return to the stop node.
    while (true) {
        Node current = circ.current();
        if (predicate.test(current)) {
            return circ;
        }
        if (current == stop) {
            break;
        }
        circ.advance(); // move to the next node in the specified direction
    }
    return circ; // Return the circulator at the stop node if no node satisfies the predicate
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null) {
        return null;
    }

    // If the start node satisfies the predicate, we return a circulator to it immediately.
    if (predicate != null && predicate.test(start)) {
        return new OuterFaceCirculator(start);
    }

    // Traverse the outer face in the specified direction.
    Node current = start;
    while (current != null && current != stop) {
        // Move to the next node in the traversal direction.
        // The actual method names (next() / prev()) depend on the Node implementation.
        current = (dir > 0) ? current.next() : current.prev();

        if (current == null) {
            break; // safety: reached an end of traversal.
        }

        if (predicate != null && predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
    }

    // If we exhaust the traversal (or reach the stop node) without finding a match,
    // return a circulator positioned at the stop node.
    return (stop != null) ? new OuterFaceCirculator(stop) : null;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null){
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null){
        throw new IllegalArgumentException("start cannot be null");
    }
    if (stop == null){
        throw new IllegalArgumentException("stop cannot be null");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    try{
        while (circ.getNode() != stop){
            Node current = circ.getNode();
            if (predicate.test(current)){
