    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes cannot be null");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    while (true) {
        // Check if the current node satisfies the predicate
        if (predicate.test(circ.node)) {
            return circ;
        }
        // If we have reached the stop node, break and return a circulator pointing to it
        if (circ.node == stop) {
            return new OuterFaceCirculator(stop);
        }
        // Move to the next or previous node depending on the direction
        if (dir > 0) {
            circ.next();
        } else {
            circ.prev();
        }
    }
}

