protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Argument 'tour' and 'graph' must not be null");
    }
    if (tour.isEmpty()) {
        // Return an empty path (start=end, no edges or vertices)
        return new GraphPathImpl<>(graph, null, null,
                Collections.emptyList(), Collections.emptyList(), 0.0);
    }
    // Compute degrees of vertices in the edge set
    Map<V, Integer> degree = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        degree.put(src, degree.getOrDefault(src, 0) + 1);
        degree.put(tgt, degree.getOrDefault(tgt, 0) + 1);
    }
    // Determine a start vertex: vertex with degree 1 if exists, otherwise arbitrary
    V start = null;
    for (Map.Entry<V, Integer> entry : degree.entrySet()) {
        if (entry.getValue() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // All vertices have degree 2 - cycle: pick source of some edge
        start = graph.getEdgeSource(tour.iterator().next());
    }
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    double weight = 0.0;
    V current = start;
    vertexList.add(current);
    Set<E> remaining = new HashSet<>(tour);
    while (!remaining.isEmpty()) {
        E nextEdge = null;
        for (E e : remaining) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current) || tgt.equals(current)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException(
                "The provided edge set does not form a continuous tour");
        }
        edgeList.add(nextEdge);
        weight += graph.getEdgeWeight(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                       ? graph.getEdgeTarget(nextEdge)
                       : graph.getEdgeSource(nextEdge);
        vertexList.add(nextVertex);
        current = nextVertex;
        remaining.remove(nextEdge);
    }
    V end = current;
    return new GraphPathImpl<>(graph, start, end, edgeList, vertexList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new SimpleGraphPath<>(graph, new ArrayList<>(), new ArrayList<>());
    }
    Map<E, Boolean> used = new HashMap<>(tour.size());
    Map<V, Integer> deg = new HashMap<>();
    Map<V, List<E>> adj = new HashMap<>();
    for (E e : tour) {
        V s = graph.getEdgeSource(e);
        V t = graph.getEdgeTarget(e);
        deg.merge(s, 1, Integer::sum);
        deg.merge(t, 1, Integer::sum);
        adj.computeIfAbsent(s, k -> new ArrayList<>()).add(e);
        adj.computeIfAbsent(t, k -> new ArrayList<>()).add(e);
    }
    V start = null;
    for (Map.Entry<V, Integer> entry : deg.entrySet()) {
        if (entry.getValue() % 2 == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null && !adj.isEmpty()) {
        start = adj.keySet().iterator().next();
    }
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    if (start != null) {
        vertexList.add(start);
        V current = start;
        while (edgeList.size() < tour.size()) {
            List<E> neigh = adj.getOrDefault(current, Collections.emptyList());
            boolean moved = false;
            for (E e : neigh) {
                if (!used.containsKey(e)) {
                    used.put(e, true);
                    edgeList.add(e);
                    V next = graph.getEdgeSource(e).equals(current) ? graph.getEdgeTarget(e) : graph.getEdgeSource(e);
                    current = next;
                    vertexList.add(current);
                    moved = true;
                    break;
                }
            }
            if (!moved) break;
        }
    }
    return new SimpleGraphPath<>(graph, vertexList, edgeList);
}

