    if(!it.hasNext()){
        return null;
    }

    // start with an arbitrary edge
    E startEdge = it.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V nextVertex = graph.getEdgeTarget(startEdge);

    vertexList.add(startVertex);
    edgeList.add(startEdge);
    visited.add(startEdge);

    // current vertex to look for edges incident on
    V current = nextVertex;
    vertexList.add(nextVertex); // insert the vertex reached by the first edge

    while(visited.size() < tour.size()){
        boolean found = false;
        for(E e : tour){
            if(visited.contains(e)){
                continue;
            }
            V s = graph.getEdgeSource(e);
            V t = graph.getEdgeTarget(e);
            if(s.equals(current)){
                // follow forward direction
                vertexList.add(t);
                current = t;
                found = true;
            }else if(t.equals(current)){
                // edge direction is opposite, reverse traversal
                vertexList.add(s);
                current = s;
                found = true;
            }
            if(found){
                edgeList.add(e);
                visited.add(e);
                break;
            }
        }
        if(!found){
            throw new IllegalArgumentException("Provided edge set does not form a continuous tour");
        }
    }

    double totalWeight = 0.0;
    for(E e : edgeList){
        totalWeight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), edgeList, totalWeight);
