private Class findClass(final String className) throws ClassNotFoundException {
    if (className == null) {
        throw new IllegalArgumentException("className must not be null");
    }
    ClassLoader contextLoader = Thread.currentThread().getContextClassLoader();
    try {
        // Attempt to load the class using the context class loader without initializing it
        return Class.forName(className, false, contextLoader);
    } catch (ClassNotFoundException e) {
        // Fallback: try with the system class loader if it differs from the context loader
        ClassLoader systemLoader = ClassLoader.getSystemClassLoader();
        if (systemLoader != null && systemLoader != contextLoader) {
            return Class.forName(className, false, systemLoader);
        }
        // Rethrow the original exception if both attempts fail
        throw e;
    }
}

