public static String stripFilenameExtension(String path){
    if (path == null){
        return null;
    }
    int lastDot = path.lastIndexOf('.');
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    if (lastDot > lastSlash && lastDot < path.length() - 1){
        return path.substring(0, lastDot);
    }
    return path;
}

public static String stripFilenameExtension(String path){
    if (path == null) return null;
    int dotIdx = path.lastIndexOf('.');
    int slashIdx = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // No dot found or dot precedes last slash (i.e., part of directory name)
    if (dotIdx == -1 || dotIdx <= slashIdx) return null;
    // Leading dot case (e.g., ".bashrc") – treat as no extension
    if (dotIdx == 0 && slashIdx == -1) return null;
    // Empty extension (ends with '.')
    if (dotIdx == path.length() - 1) return null;
    return path.substring(0, dotIdx);
}

