    }
    int lastDotIndex = path.lastIndexOf('.');
    if (lastDotIndex == -1) {
        return null;
    }
    // If the dot is the last character, it's not really an extension
    if (lastDotIndex == path.length() - 1) {
        return null;
    }
    int lastSeparatorIndex = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // The dot must come after the last file separator
    if (lastDotIndex <= lastSeparatorIndex) {
        return null;
    }
    return path.substring(0, lastDotIndex);
}

public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    // Determine last path separator (covers both Unix '/' and Windows '\\')
    int lastSepUnix = path.lastIndexOf('/');
    int lastSepWindows = path.lastIndexOf('\\');
    int lastSeparator = Math.max(lastSepUnix, lastSepWindows);

    // Find the last dot in the path
    int lastDot = path.lastIndexOf('.');

    // If there is no dot, if the dot precedes the last separator, or if the dot is the last character (empty extension), return null
    if (lastDot == -1 || lastDot <= lastSeparator || lastDot == path.length() - 1) {
        return null;
    }

    // Return the substring up to the last dot (excluding the dot)
    return path.substring(0, lastDot);
}

