private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    long totalSum = 0;
    for (int val : bounds) {
        totalSum += val;
    }
    List<Integer> suffix = new ArrayList<>(Collections.nCopies(n, 0));
    long suffixSum = 0;
    for (int i = n - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        suffix.set(i, (int) suffixSum);
    }
    return new Pair<>(suffix, totalSum);
}

