public static final <V> void reverse(V[] arr,int from,int to){
    if (arr == null) throw new NullPointerException("Array is null");
    int len = arr.length;
    if (from < 0 || to >= len) throw new IndexOutOfBoundsException("from or to index out of bounds");
    if (from > to) throw new IllegalArgumentException("from index greater than to index");
    int i = from, j = to;
    while (i < j){
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

