    }

    // Grab source list's boundaries
    Node<E> srcFirst = list.first;
    Node<E> srcLast = list.last;

    // If this list is empty, just take over all nodes
    if (this.isEmpty()) {
        this.first = srcFirst;
        this.last = srcLast;
    } else {
        // Link the end of this list to the start of the source list
        this.last.next = srcFirst;
        srcFirst.prev = this.last;
        this.last = srcLast;
    }

    // Update the size counts
    this.size += list.size;

    // Clear the source list
    list.first = null;
    list.last = null;
    list.size = 0;
