private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null || keys.isEmpty()){
        return new ArrayList<>();
    }
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort(Comparator.naturalOrder());
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys){
        int lo = 0, hi = sorted.size() - 1, floor = -1;
        while (lo <= hi){
            int mid = (lo + hi) >>> 1;
            K midVal = sorted.get(mid);
            int cmp = midVal.compareTo(key);
            if (cmp <= 0){
                floor = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        bounds.add(floor);
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new java.util.ArrayList<>();
    if (keys == null) {
        return lowerBounds;
    }
    for (K keyObj : keys) {
        try {
            if (keyObj == null) {
                lowerBounds.add(null);
                continue;
            }
            int keyVal;
            try {
                keyVal = ((Integer) keyObj).intValue();
            } catch (ClassCastException e) {
                lowerBounds.add(null);
                continue;
            }
            int maxLower = Integer.MIN_VALUE;
            boolean found = false;
            for (K otherObj : keys) {
                if (otherObj == null) continue;
                int val;
                try {
                    val = ((Integer) otherObj).intValue();
                } catch (ClassCastException e2) {
                    continue;
                }
                if (val <= keyVal) {
                    if (!found || val > maxLower) {
                        maxLower = val;
                        found = true;
                    }
                }
            }
            lowerBounds.add(found ? maxLower : null);
        } catch (Exception ex) {
            lowerBounds.add(null);
        }
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null) {
        return lowerBounds;
    }
    for (int i = 0; i < keys.size(); i++) {
        int bestIndex = -1;
        K bestCandidate = null;
        K current = keys.get(i);
        for (int j = 0; j < i; j++) {
            K candidate = keys.get(j);
            if (candidate == null || current == null) {
                continue;
            }
            @SuppressWarnings("unchecked")
            int cmp = ((Comparable<Object>) candidate).compareTo(current);
            if (cmp <= 0 && (bestCandidate == null || ((Comparable<Object>) candidate).compareTo(bestCandidate) > 0)) {
                bestCandidate = candidate;
                bestIndex = j;
            }
        }
        lowerBounds.add(bestIndex);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> bounds = new java.util.ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        if (key == null) {
