            } else {
                bounds.add(key.hashCode());
            }
        } catch (Exception e) {
            bounds.add(0);
        }
    }
    return bounds;
}

private void pop(final String descriptor){
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor must not be null");
    }
    int count = 0;
    // Method descriptor
    if (descriptor.charAt(0) == '(') {
        int i = 1;
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'L') { // object type
                i = descriptor.indexOf(';', i) + 1;
            } else if (c == '[') { // array type
                do {
                    i++;
                    c = descriptor.charAt(i);
                } while (c == '[');
                if (c == 'L') {
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    i++; // primitive component
                }
            } else { // primitive
                i++;
            }
            count++; // one argument type
        }
    } else { // single type descriptor
        count = 1;
    }

    // Pop the described types from the output frame stack.
    // Assume an existing stack named 'outputFrameStack' with pop() and isEmpty() methods.
    for (int j = 0; j < count; j++) {
        if (!outputFrameStack.isEmpty()) {
            outputFrameStack.pop();
        } else {
            throw new IllegalStateException("Output frame stack underflow while popping descriptor: " + descriptor);
        }
    }
}

private void pop(final String descriptor){
    // Count how many types need to be removed from the output frame stack
    int count = 0;
    if (descriptor == null || descriptor.isEmpty()) {
        return; // Nothing to pop
    }
    // Method descriptor: starts with '('
    if (descriptor.charAt(0) == '(') {
        int i = 1;
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == ')') {
                break;
            }
            if (c == 'L') { // object type
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon < 0) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                i = semicolon + 1;
                count++;
                continue;
            }
            if (c == '[') { // array type
                // consume array brackets
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                // after brackets, either object or primitive
                if (i < descriptor.length() && descriptor.charAt(i) == 'L') {
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon < 0) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    i = semicolon + 1;
                } else {
                    // primitive type after brackets
                    i++;
                }
                count++;
                continue;
            }
            // Primitive type (boolean, byte, char, double, float, int, long, short)
            // one character descriptor
            i++;
            count++;
        }
    } else {
        // Descriptor is a single type (not a method descriptor)
        count = 1;
    }

    // Pop the counted number of elements from the output frame stack
    for (int j = 0; j < count; j++) {
        if (outputFrameStack.isEmpty()) {
            throw new IllegalStateException(
                "Output frame stack underflow while popping type: " + descriptor
            );
        }
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor){
    int slots = 0;
    try{
        if(descriptor==null){return;}
        if(descriptor.startsWith("(")){
            int end = descriptor.indexOf(')');
            if(end!=-1){
                for(int i=1;i<end;i++){
                    char c = descriptor.charAt(i);
                    switch(c){
                        case 'J':
                        case 'D':
                            slots+=2;
                            break;
                        default:
                            slots+=1;
                            break;
                    }
                }
            }
        }else{
            for(int i=0;i<descriptor.length();i++){
                char c = descriptor.charAt(i);
                switch(c){
                    case 'J':
                    case 'D':
                        slots+=2;
                        break;
                    default:
                        slots+=1;
                        break;
                }
            }
        }
    }catch(IndexOutOfBoundsException|NullPointerException e){
        return;
    }
    for(int i=0;i<slots;i++){
        if(!outputFrameStack.isEmpty()){
            outputFrameStack.pop();
        }
    }
}

private void pop(final String descriptor){
    if (descriptor == null){
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    int count = 0;
    for (int i = 0; i < descriptor.length(); ){
        char c = descriptor.charAt(i);
        switch (c){
            case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
                count++;
                i++;
                break;
            case 'L':
                count++;
                i = descriptor.indexOf(';', i);
                if (i < 0 || i >= descriptor.length()){
                    throw new IllegalArgumentException("Invalid object descriptor: " + descriptor);
                }
                i++; // skip ';'
                break;
            case '[':
                // array type – count as a single slot
                count++;
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) == '['){
                    i++;
                }
                if (i >= descriptor.length()){
                    throw new IllegalArgumentException("Invalid array descriptor: " + descriptor);
                }
                if (descriptor.charAt(i) == 'L'){
                    i = descriptor.indexOf(';', i);
                    if (i < 0){
                        throw new IllegalArgumentException("Invalid array object descriptor: " + descriptor);
                    }
                }
                i++; // skip component type (or ';')
                break;
            case '(':
                int end = descriptor.indexOf(')', i);
                if (end < 0){
                    throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
                }
                int pos = i + 1;
                while (pos < end){
                    char d = descriptor.charAt(pos);
                    if (d == '['){
                        while (pos < end && descriptor.charAt(pos) == '['){
                            pos++;
                        }
                        if (pos < end && descriptor.charAt(pos) == 'L'){
                            pos = descriptor.indexOf(';', pos);
                            if (pos < 0){
                                throw new IllegalArgumentException("Invalid array object in method descriptor: " + descriptor);
                            }
                        }
                        pos++; // skip component type
                    } else if (d == 'L'){
                        pos = descriptor.indexOf(';', pos);
                        if (pos < 0){
                            throw new IllegalArgumentException("Invalid object type in method descriptor: " + descriptor);
                        }
                        pos++; // skip ';'
                    } else {
                        pos++; // primitive
                    }
                    count++;
                }
                i = end + 1;
                break;
            case ')':
                i++;
                break;
            default:
                throw new IllegalArgumentException("Unsupported descriptor character '" + c + "' in " + descriptor);
        }
    }
    for (int j = 0; j < count; j++){
        if (outputStack == null || outputStack.isEmpty()){
            throw new IllegalStateException("Stack underflow while popping descriptor: " + descriptor);
        }
        outputStack.pop();
    }
}

