private List<Integer> computeUpperBounds(List<K> keys){
    // Guard against null input
    if (keys == null || keys.isEmpty()){
        return new ArrayList<Integer>();
    }
    try{
        // Prepare the result list with the same size as keys
        List<Integer> bounds = new ArrayList<>(keys.size());
        // Iterate over each key to compute its upper bound
        for (int i = 0; i < keys.size(); i++){
            K currentKey = keys.get(i);
            if (currentKey == null){
                // If key is null treat it as lowest value; bound is 0
                bounds.add(0);
                continue;
            }
            int upperBound = 0;
            // Count how many keys are strictly greater than currentKey
            for (int j = 0; j < keys.size(); j++){
                K compareKey = keys.get(j);
                if (compareKey == null){
                    continue;
                }
                // We assume K implements Comparable
                @SuppressWarnings("unchecked")
                Comparable<Object> cmpKey = (Comparable<Object>) compareKey;
                if (cmpKey.compareTo(currentKey) > 0){
                    upperBound++;
                }
            }
            bounds.add(upperBound);
        }
        return bounds;
    }catch(ClassCastException e){
        // If keys are not comparable, return empty list or throw RuntimeException
        throw new IllegalArgumentException("Keys must implement Comparable");
    }
}

