public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    if (s.isEmpty()) {
        return s;
    }
    StringBuilder sb = new StringBuilder(s.length() * 2);
    for (int i = 0; i < s.length(); i++) {
