public static String applyRelativePath(String path,String relativePath){
    if (path == null || path.isEmpty()){
        return (relativePath == null)? "" : relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()){
        return path;
    }
    java.nio.file.Path base = java.nio.file.Paths.get(path);
    java.nio.file.Path resolved = base.resolve(relativePath);
    java.nio.file.Path normalized = resolved.normalize();
    String result = normalized.toString();
    // Convert system-specific separator to forward slash
    if (java.io.File.separatorChar != '/'){
        result = result.replace(java.io.File.separatorChar,'/');
    }
    return result;
}

