public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSepUnix = filename.lastIndexOf('/');
    int lastSepWindows = filename.lastIndexOf('\\');
    int lastSeparator = Math.max(lastSepUnix, lastSepWindows);
    if (lastSeparator > lastDot) {
        return -1;
    }
    return lastDot;
}

