public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = read(); // reads a single byte, returns -1 on EOF
        if (b == -1) {
            return 0; // EOF reached, return zero tag
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag; // end of varint
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed Tag: varint too long");
        }
    }
}

