                        result.add(ts);
                        break;
                    }
                }
            }
        }
    } catch (ClassNotFoundException e) {
        // ignore class not found, return whatever has been successfully parsed
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return snapshots;
    }
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Assume each line starts with a timestamp followed by a comma.
            try {
                String[] parts = line.split(",", 2);
                if (parts.length == 0) {
                    continue;
                }
                long timestamp = Long.parseLong(parts[0].trim());
                boolean inRange = true;
                if (timeRanges != null && !timeRanges.isEmpty()) {
                    inRange = false;
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        long start = range.getStartTime();
                        long end = range.getEndTime();
                        if (timestamp >= start && timestamp <= end) {
                            inRange = true;
                            break;
                        }
                    }
                }
                if (inRange) {
                    // Create a ThreadSnapshot instance.
                    // Assuming a constructor that accepts the raw line or a suitable constructor exists.
                    ThreadSnapshot snapshot = new ThreadSnapshot(line);
                    snapshots.add(snapshot);
                }
            } catch (NumberFormatException nfe) {
                // Skip lines that don't conform to the expected format.
            }
        }
    }
    return snapshots;
}
